          logInner.castShadow = true; logInner.receiveShadow = true; logGroup.add(logInner);

          // Các nhánh gỗ mọc tủa ra đệ quy (3 nhánh đệ quy bằng recTree)
          const branch1 = new THREE.Group();
          branch1.position.set(0.3, 1.2, 0.4);
