          const stumpTopMat = new THREE.MeshLambertMaterial({ color: 0xc8a576, map: stumpRingTex }); // màu nền mặt cắt tối dã dặn hơn

          // Vỏ cây xù xì bên ngoài (Đường kính tăng 4 lần: R_top = 0.96, R_bottom = 1.12)
