          for (const [sx, xx] of [[-1, x0], [1, x1]]) { const r = Math.min(46, h * 0.42); lobes.push([xx - sx * 10, (y0 + y1) / 2, r]); lobes.push([xx - sx * 22, y0 + h * 0.22, r * 0.72]); lobes.push([xx - sx * 22, y1 - h * 0.2, r * 0.66]); }
